<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Holder\TenantConfigForceMfaAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigForceMfaAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantConfigForceMfaAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that isForceMfa returns null on a freshly created holder.
     */
    public function testForceMfaNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigForceMfaAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isForceMfaAssigned());
        $this->assertNull($holder->isForceMfa());
    }
}
class ImplWithTenantConfigForceMfaAttributeHolderUnitTest
{
    use TenantConfigForceMfaAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedForceMfaRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultForceMfa();
    }
}
